import { Link } from 'react-router-dom';
import React, { useState, useEffect } from 'react';
import './Aiiot.css';

const AIIOT_INDEX = () => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [heroImages, setHeroImages] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  
  const [activeCategory, setActiveCategory] = useState('Air Quality');
  const [isMegaMenuOpen, setIsMegaMenuOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // --- MEGA MENU DATA ---
  const productMenuData = {
    'Air Quality': {
      title: 'Air Quality Monitoring',
      description: 'Precision sensors for indoor and outdoor environments.',
      items: [
        { name: 'Indoor Monitor', image: '/sensor_modules/aqicrop.jpeg', link: '/product-details/indoor-monitor' },
        { name: 'Outdoor Station', image: '/sensor_modules/aqi1.jpeg', link: '/product-details/outdoor-station' },
        { name: 'Gas Sensors', image: 'https://images.unsplash.com/photo-1621905252507-b35492cc74b4?w=400', link: '/product-details/gas-sensors' }
      ]
    },
    'Water Solutions': {
      title: 'Water Management',
      description: 'Flood alerts and distribution logic.',
      items: [
        { name: 'Flood Alert System', image: '/sensor_modules/river1.jpg', link: '/product-details/flood-alert' },
        { name: 'Level Sensors', image: 'https://images.unsplash.com/photo-1581092918056-0c4c3acd3789?w=400', link: '/product-details/level-sensors' },
        { name: 'Distribution Net', image: '/sensor_modules/distribution.jpeg', link: '/product-details/distribution-net' }
      ]
    },
    'Weather': {
      title: 'Weather Stations',
      description: 'Hyper-local weather data collection.',
      items: [
        { name: 'Auto Weather Station', image: '/sensor_modules/weather.jpg', link: '/product-details/weather-station' },
        { name: 'Rain Gauges', image: 'https://images.unsplash.com/photo-1590055531860-6902633df018?w=400', link: '/product-details/rain-gauge' }
      ]
    },
    'Training': {
      title: 'Skill Development',
      description: 'Kits and workshops for students.',
      items: [
        { name: 'IoT Starter Kits', image: '/sensor_modules/skill.jpg', link: '/product-details/iot-starter-kit' },
        { name: 'PCB Workshops', image: 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=400', link: '/product-details/pcb-workshop' }
      ]
    }
  };

  const projectIdMap = {
    'Air Quality Monitoring': 'intelligent-sensor',
    'Smart Water Level Monitoring': 'water-level',
    'Digital Water Distribution': 'digital-water',
    'Startup & Skill Development': 'startup-skill',
  };

  useEffect(() => {
    if (window.feather) { window.feather.replace(); }
    const scrollElements = document.querySelectorAll(".reveal-on-scroll");
    const elementInView = (el, dividend = 1) => {
      const elementTop = el.getBoundingClientRect().top;
      return elementTop <= (window.innerHeight || document.documentElement.clientHeight) / dividend;
    };
    const displayScrollElement = (element) => element.classList.add("is-visible");
    const handleScrollAnimation = () => {
      scrollElements.forEach((el) => {
        if (elementInView(el, 1.25)) displayScrollElement(el);
      });
    };
    handleScrollAnimation(); 
    window.addEventListener("scroll", handleScrollAnimation);
    setupCarousel();
    return () => { window.removeEventListener("scroll", handleScrollAnimation); };
  }, []);

  const setupCarousel = () => {
    const localImages = [
      '/carousel-images/aiiot1.jpg',
      '/carousel-images/aiiot2.jpeg',
      '/carousel-images/aiiot3.jpg',
      '/carousel-images/aiiot4.jpg',
    ];
    setHeroImages(localImages);
    setIsLoading(false);
  };

  useEffect(() => {
    if (heroImages.length === 0) return;
    const interval = setInterval(() => {
      setCurrentImageIndex((prevIndex) => (prevIndex + 1) % heroImages.length);
    }, 4000);
    return () => clearInterval(interval);
  }, [heroImages]);

  const handleIndicatorClick = (index) => { setCurrentImageIndex(index); };

  const teamMembers = [
    { name: "Dr. Ajay Kumar", role: "Principal Investigator", description: "Associate Professor", image: "/faculties/ajay.jpeg" },
    { name: "Mr. Albins Paul", role: "Co-Investigator", description: "Assistant Professor", image: "/faculties/albins.jpg" },
    { name: "Prof. P.V. Rajaraman", role: "Co-Investigator", description: "Assistant Professor", image: "/faculties/rajaraman.jpg" },
    { name: "Mr. Abhijith Pm", role: "Project Associate", description: "", image: "/faculties/abhijith.jpeg" },
    { name: "Mrs. Hasna Hameed", role: "Project Associate", description: "", image: "/faculties/hasna2.jpeg" },
    { name: "Ms. Arathy Surendran", role: "Project Associate", description: "", image: "/faculties/arathy.jpeg" },
    { name: "Mr. Bhagyaraj J", role: "Project Assistant", description: "", image: "/faculties/bhagyaraj.jpeg" },
    { name: "Mr. Amaljith N Raj", role: "Project Assistant", description: "", image: "/faculties/amaljith.jpeg" },
    { name: "Mrs. Jibina EA", role: "Project Assistant", description: "", image: "/faculties/jibinaea.jpeg" }
  ];

  const projects = [
    { title: "Air Quality Monitoring", description: "Real-time monitoring and management of environmental pollutants.", image: "/sensor_modules/aqicrop.jpeg" },
    { title: "Smart Water Level Monitoring", description: "Real-time water level tracking with flood alerts.", image: "/sensor_modules/river1.jpg" },
    { title: "Digital Water Distribution", description: "Virtual replica of water distribution networks using Digital Twin.", image: "/sensor_modules/distribution.jpeg" },
    { title: "Startup & Skill Development", description: "Building a vibrant startup ecosystem with hands-on IoT training.", image: "/sensor_modules/skill.jpg" }
  ];

  return (
    <div className="aiiot-page-container">
      {/* Header Section */}
      <header className="aiiot-header">
        <div className="nav-container">
            {/* LOGO */}
            <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: '1rem', textDecoration: 'none', zIndex: 1001 }}>
              <div className="logo-box">
                <img src="/logo/logo.png" alt="Logo" style={{ height: '100%', width: 'auto' }} />
              </div>
              <div style={{ display: 'flex', flexDirection: 'column' }}>
                <span style={{ fontSize: '1.25rem', fontWeight: 700, color: '#1e293b', lineHeight: 1.2 }}>AI-IoT Innovations</span>
                <span style={{ fontSize: '0.75rem', color: '#64748b', fontWeight: 500 }}>Adi Shankara</span>
              </div>
            </Link>

            {/* DESKTOP NAV */}
            <div className="desktop-nav">
              <a href="#about" className="nav-link">About</a>
              <a href="#projects" className="nav-link">Solutions</a>
              
              {/* MEGA MENU TRIGGER */}
              <div 
                className="mega-menu-wrapper"
                onMouseEnter={() => setIsMegaMenuOpen(true)}
                onMouseLeave={() => setIsMegaMenuOpen(false)}
              >
                <Link to="/products" className="nav-link product-trigger">
                  Products <span>▾</span>
                </Link>

                <div className={`mega-menu-container ${isMegaMenuOpen ? 'visible' : ''}`}>
                  <div className="mega-menu-sidebar">
                    {Object.keys(productMenuData).map((key) => (
                      <div key={key} className={`mega-sidebar-item ${activeCategory === key ? 'active' : ''}`} onMouseEnter={() => setActiveCategory(key)}>
                        {key} <span>›</span>
                      </div>
                    ))}
                  </div>
                  <div className="mega-menu-content">
                    <div className="mega-content-header">
                      <h4>{productMenuData[activeCategory].title}</h4>
                      <p>{productMenuData[activeCategory].description}</p>
                    </div>
                    <div className="mega-grid">
                      {productMenuData[activeCategory].items.map((item, idx) => (
                        <Link to={item.link} key={idx} className="mega-product-card">
                           <div className="mega-img-box"><img src={item.image} alt={item.name} /></div>
                           <span>{item.name}</span>
                        </Link>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
              {/* END MEGA MENU */}

              <Link to="/resources" className="nav-link">Resources</Link>
              <a href="#team" className="nav-link">Team</a>
              <a href="#contact" className="nav-btn-primary">Contact</a>
            </div>

            {/* MOBILE HAMBURGER */}
            <button className="mobile-nav-toggle" onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
              {isMobileMenuOpen ? '✕' : '☰'}
            </button>
        </div>

        {/* MOBILE MENU */}
        <div className={`mobile-menu-wrapper ${isMobileMenuOpen ? 'open' : ''}`}>
            <a href="#about" className="mobile-nav-link" onClick={() => setIsMobileMenuOpen(false)}>About</a>
            <a href="#projects" className="mobile-nav-link" onClick={() => setIsMobileMenuOpen(false)}>Solutions</a>
            <Link to="/products" className="mobile-nav-link" onClick={() => setIsMobileMenuOpen(false)}>Products</Link>
            <Link to="/resources" className="mobile-nav-link" onClick={() => setIsMobileMenuOpen(false)}>Resources</Link>
            <a href="#team" className="mobile-nav-link" onClick={() => setIsMobileMenuOpen(false)}>Team</a>
            <a href="#contact" className="mobile-nav-link" onClick={() => setIsMobileMenuOpen(false)}>Contact Us</a>
        </div>
      </header>

      {/* Main Content - PADDING REMOVED HERE, HANDLED IN CSS */}
      <main style={{ flex: 1, paddingTop: '5rem' }}>
        
        {/* Hero Section */}
        <section className="hero-gradient reveal-on-scroll">
          <div className="container" style={{ maxWidth: '80rem', margin: '0 auto', padding: '0 1rem' }}>
            <div style={{ display: 'flex', gap: '3rem', alignItems: 'center', flexDirection: 'row' }}> {/* Flex Direction handled by CSS Media Query now */}
              <div style={{ flex: 1 }}>
                <span style={{ display: 'inline-block', padding: '0.5rem 1rem', background: '#eff6ff', color: '#2563eb', fontSize: '0.875rem', borderRadius: '9999px', marginBottom: '1.5rem' }}>
                  Sponsored by MeitY
                </span>
                <h1 style={{ fontSize: '3.5rem', fontWeight: 700, color: '#1e293b', marginBottom: '1.5rem', lineHeight: 1.1 }}>
                  Center for AI-IoT <span style={{ color: '#3b82f6' }}>Innovations</span>
                </h1>
                <p style={{ fontSize: '1.125rem', color: '#475569', marginBottom: '2rem' }}>
                  Where electronics hardware meets Artificial Intelligence.
                </p>
                <a href="#projects" className="nav-btn-primary">Explore Projects →</a>
              </div>
              <div style={{ flex: 1 }}>
                <div id="hero-image-container" style={{ position: 'relative', width: '100%', height: '400px', overflow:'hidden', borderRadius:'1rem' }}>
                    <img src={heroImages[currentImageIndex]} alt="Hero" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* About Section */}
        <section id="about" className="reveal-on-scroll" style={{background:'#fff'}}>
          <div style={{ maxWidth: '80rem', margin: '0 auto', padding: '0 1rem' }}>
            <div style={{ textAlign: 'center', marginBottom: '3rem' }}>
              <h2 style={{ fontSize: '2.25rem', fontWeight: 700, color: '#1e293b' }}>About Our Center</h2>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '3rem' }}>
               <div>
                  <p style={{ color: '#475569', lineHeight: 1.8 }}>The Center provides resources for both theoretical research and practical applications...</p>
               </div>
               <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                  <div style={{padding:'1rem', border:'1px solid #e2e8f0', borderRadius:'0.5rem'}}>
                    <h3>⚡ Innovation</h3>
                  </div>
                  <div style={{padding:'1rem', border:'1px solid #e2e8f0', borderRadius:'0.5rem'}}>
                    <h3>💻 Tech</h3>
                  </div>
               </div>
            </div>
          </div>
        </section>

        {/* Projects Section */}
        <section id="projects" className="reveal-on-scroll">
          <div style={{ maxWidth: '80rem', margin: '0 auto', padding: '0 1rem' }}>
            <h2 style={{ fontSize: '2.25rem', fontWeight: 700, color: '#1e293b', textAlign:'center', marginBottom: '3rem' }}>Our Projects</h2>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '3rem' }}>
              {projects.map((project, index) => {
                const projectId = projectIdMap[project.title] || 'unknown';
                return (
                  <div key={index} className={`project-card ${index % 2 === 0 ? 'layout-normal' : 'layout-reverse'}`}>
                    <div className="project-image-wrapper">
                      <img src={project.image} alt={project.title} />
                    </div>
                    <div className="project-content-wrapper">
                      <h3 style={{ fontSize: '1.75rem', fontWeight: 700, marginBottom:'1rem' }}>{project.title}</h3>
                      <p style={{ color: '#475569', marginBottom: '1.5rem' }}>{project.description}</p>
                      <Link to={`/project/${projectId}`} className="nav-btn-primary" style={{display:'inline-block'}}>View Case Study</Link>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </section>

        {/* Team Section */}
        <section id="team" className="reveal-on-scroll" style={{ background: '#f8fafc' }}>
          <div style={{ maxWidth: '80rem', margin: '0 auto', padding: '0 1rem' }}>
            <h2 style={{ textAlign: 'center', fontSize: '2.25rem', fontWeight: 700, marginBottom: '3rem' }}>Our Team</h2>
            <div className="grid-container" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '2rem' }}>
              {teamMembers.map((member, index) => (
                <div key={index} style={{ background: 'white', padding: '1.5rem', borderRadius: '1rem', textAlign: 'center', boxShadow:'0 4px 6px -1px rgba(0,0,0,0.1)' }}>
                  <img src={member.image} alt={member.name} style={{ width: '100px', height: '100px', borderRadius: '50%', objectFit: 'cover', marginBottom: '1rem' }} />
                  <h4 style={{ fontWeight: 700 }}>{member.name}</h4>
                  <p style={{ color: '#3b82f6', fontSize: '0.875rem' }}>{member.role}</p>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* Contact */}
        <section id="contact" style={{ padding: '4rem 1rem', textAlign: 'center' }}>
           <h2>Contact Us</h2>
           <p style={{marginBottom:'2rem'}}>aiiot@adishankara.ac.in</p>
        </section>

      </main>

      <footer style={{ background: '#1e293b', color: 'white', padding: '2rem 1rem', textAlign:'center' }}>
          <p>&copy; 2025 Center for AI-IoT Innovations.</p>
      </footer>
    </div>
  );
};

export default AIIOT_INDEX;
